public class LibraryMemberBean{static class LibraryMember{private String membershipId,name,securityAnswer;private boolean premiumMember;public LibraryMember(){}public String getMembershipId(){return membershipId;}public void setMembershipId(String id){if(membershipId==null)membershipId=id;}public String getName(){return name;}public void setName(String n){name=n;}public boolean isPremiumMember(){return premiumMember;}public void setPremiumMember(boolean p){premiumMember=p;}public void setSecurityAnswer(String a){securityAnswer=Integer.toHexString(a.hashCode());}}}